    public static void main(String[] args) {
        System.out.println(new Builder().add("Hello").add("World").build());
    }
}

exercises.starter_code:
static class Circle { double radius; }
public class Main {
    public static void main(String[] args) { Circle c = new Circle(); c.radius = 5.0; }
}

exercises.solution:
public class Main {
    static class Circle {
        double radius;
        double area() { return Math.PI * radius * radius; }
        double perimeter() { return 2 * Math.PI * radius; }
    }

    public static void main(String[] args) {
        Circle c = new Circle(); c.radius = 5.0;
        System.out.println(c.area());
        System.out.println(c.perimeter());
    }
}

